const std = @import("std"); const http = std.http; const fla2 = std.compress.flate; const safe = @import("nt-safe-guar.zig"); const urln = @import("ut-urlz-norm.zig"); const spec = @import("pa-spec-read.zig"); const cdp2 = @import("nt-brow-cdpz.zig");
const CF = .{ .redb = 4096, .trnb = 8192, .tick = 10 };
pub const Opts = struct { time_mill: u32 = 30000, body_maxz: usize = 5242880, priv: bool = false };
pub const Resp = struct { code: u16, ctyp: []const u8, body: []const u8 };
const Jobz = struct { gpaz: std.mem.Allocator, iozz: std.Io, meth: []u8, urlz: []u8, body: []u8, heds: []http.Header, hbuf: [][]u8, opts: Opts, done: std.atomic.Value(bool) = .init(false), refs: std.atomic.Value(u32) = .init(2), code: u16 = 0, ctyp: []u8 = &.{}, rbod: []u8 = &.{}, errn: ?anyerror = null,
fn relz(self: *Jobz) void { if (self.refs.fetchSub(1, .acq_rel) != 1) return; const gpaz = self.gpaz; gpaz.free(self.meth); gpaz.free(self.urlz); gpaz.free(self.body); for (self.hbuf) |hbzz| gpaz.free(hbzz); gpaz.free(self.hbuf); gpaz.free(self.heds); gpaz.free(self.ctyp); gpaz.free(self.rbod); gpaz.destroy(self); } };
fn run2(jobz: *Jobz) !void { const gpaz = jobz.gpaz; const part = try urln.urlzSpli(jobz.urlz); try safe.hostChek(jobz.iozz, part.host, jobz.opts.priv); const uriz = std.Uri.parse(jobz.urlz) catch return error.BadUrl; const mthd = std.meta.stringToEnum(http.Method, jobz.meth) orelse return error.BadSpec; var clnt: http.Client = .{ .allocator = gpaz, .io = jobz.iozz }; defer clnt.deinit(); var req2 = try clnt.request(mthd, uriz, .{ .keep_alive = false, .redirect_behavior = .unhandled, .extra_headers = jobz.heds }); defer req2.deinit(); if (jobz.body.len > 0) { req2.transfer_encoding = .{ .content_length = jobz.body.len }; try req2.sendBodyComplete(jobz.body); } else { try req2.sendBodiless(); } var redb: [CF.redb]u8 = undefined; var resp = try req2.receiveHead(&redb); jobz.code = @backingInt(resp.head.status); var ctzz: []const u8 = ""; var iter = resp.head.iterateHeaders(); while (iter.next()) |item| { if (std.ascii.eqlIgnoreCase(item.name, "content-type")) ctzz = item.value; } jobz.ctyp = try gpaz.dupe(u8, ctzz); const trnb = try gpaz.alloc(u8, CF.trnb); defer gpaz.free(trnb); const winb = try gpaz.alloc(u8, fla2.max_window_len); defer gpaz.free(winb); var deco: http.Decompress = undefined; const rdrz = resp.readerDecompressing(trnb, &deco, winb); jobz.rbod = rdrz.allocRemaining(gpaz, .limited(jobz.opts.body_maxz)) catch |err3| switch (err3) { error.StreamTooLong => return error.TooBig, error.OutOfMemory => return error.OutOfMemory, error.ReadFailed => return resp.bodyErr() orelse error.ReadFailed }; }
fn work(jobz: *Jobz) void { run2(jobz) catch |err3| { jobz.errn = err3; }; jobz.done.store(true, .release); jobz.relz(); }
pub fn specFetc(gpaz: std.mem.Allocator, aren: std.mem.Allocator, iozz: std.Io, spcz: spec.Spec, opts: Opts) !Resp { const jobz = try gpaz.create(Jobz); const meth = try gpaz.dupe(u8, spcz.meth); const urlz = try gpaz.dupe(u8, spcz.urlz); const body = try gpaz.dupe(u8, spcz.body); const heds = try gpaz.alloc(http.Header, spcz.hdrs.len); const hbuf = try gpaz.alloc([]u8, spcz.hdrs.len * 2); for (spcz.hdrs, 0..) |item, ind3| { hbuf[ind3 * 2] = try gpaz.dupe(u8, item.name); hbuf[ind3 * 2 + 1] = try gpaz.dupe(u8, item.valu); heds[ind3] = .{ .name = hbuf[ind3 * 2], .value = hbuf[ind3 * 2 + 1] }; } jobz.* = .{ .gpaz = gpaz, .iozz = iozz, .meth = meth, .urlz = urlz, .body = body, .heds = heds, .hbuf = hbuf, .opts = opts }; const thr2 = std.Thread.spawn(.{}, work, .{jobz}) catch { jobz.relz(); jobz.relz(); return error.Unexpected; }; thr2.detach(); const dead = cdp2.nowzMill(iozz) + opts.time_mill; while (!jobz.done.load(.acquire)) { if (cdp2.nowzMill(iozz) > dead) { jobz.relz(); return error.Timeout; } std.Io.sleep(iozz, .fromMilliseconds(CF.tick), .awake) catch {}; } defer jobz.relz(); if (jobz.errn) |err3| return err3; return .{ .code = jobz.code, .ctyp = try aren.dupe(u8, jobz.ctyp), .body = try aren.dupe(u8, jobz.rbod) }; }
